-- ---- 2. the four Cata-only summon targets ----------------------------------
-- 74723 / 76963 / 77627 / 79825 are SUMMON spells whose EffectMiscValue names a
-- creature that exists on neither side, raw or offset. Downporting the spell
-- alone would leave it summoning nothing -- exactly the trap 145_ hit with the
-- TRANSFORM spell 97678. Cloned at +3,600,000 to match both the callers
-- (3638896 Blazebound Elemental x20, 3641027 Wormwing Screecher x46, 3641500
-- Twilight Scorchlord x92, 3639931 Grove Tender x10) and the section-1 remap.
--
-- Source is nelt_world, using MoltenFront/16_'s column mapping verbatim. None of
-- the four carries AIName, so no smart_scripts rows are owed and none of them
-- will report "SmartAI enabled but no SmartAI entries". lootid is forced to 0:
-- only 41501 has any in source, and a summoned guardian that despawns is not a
-- loot source, so keeping it would only add a fresh dead-lootid warning.
--
-- Displays 17200 / 1126 / 11686 / 1405 / 23870 were checked against the live
-- server CreatureDisplayInfo.dbc (all present) AND creature_model_info (all
-- present), so no third-layer display backfill is owed.
SET @OFF := 3600000;

DELETE FROM acore_world.`creature_template` WHERE `entry` IN (3640080,3641153,3641501,3642835);

INSERT INTO acore_world.`creature_template`
(`entry`,`KillCredit1`,`KillCredit2`,`name`,`subname`,`IconName`,`gossip_menu_id`,`minlevel`,`maxlevel`,`exp`,`faction`,`npcflag`,`speed_walk`,`speed_run`,`speed_swim`,`speed_flight`,`rank`,`dmgschool`,`DamageModifier`,`BaseAttackTime`,`RangeAttackTime`,`BaseVariance`,`RangeVariance`,`unit_class`,`unit_flags`,`unit_flags2`,`dynamicflags`,`family`,`type`,`type_flags`,`lootid`,`pickpocketloot`,`skinloot`,`PetSpellDataId`,`VehicleId`,`mingold`,`maxgold`,`AIName`,`MovementType`,`HoverHeight`,`HealthModifier`,`ManaModifier`,`ArmorModifier`,`RacialLeader`,`movementId`,`RegenHealth`,`flags_extra`,`ScriptName`,`VerifiedBuild`)
SELECT entry+@OFF, IF(KillCredit1>0,KillCredit1+@OFF,0), IF(KillCredit2>0,KillCredit2+@OFF,0), name, subname, IconName, gossip_menu_id, minlevel, maxlevel, LEAST(exp,2), faction_A, npcflag, speed_walk, speed_run, speed_swim, speed_fly, `rank`, dmgschool, dmg_multiplier, baseattacktime, rangeattacktime, 1, 1, unit_class, unit_flags, unit_flags2, dynamicflags, family, type, type_flags, 0, 0, 0, PetSpellDataId, VehicleId, mingold, maxgold,
       AIName,
       MovementType, HoverHeight, Health_mod, Mana_mod, Armor_mod, RacialLeader, movementId, RegenHealth, flags_extra, '', 0
FROM nelt_world.creature_template
WHERE entry IN (40080,41153,41501,42835);

DELETE FROM acore_world.`creature_template_model` WHERE `CreatureID` IN (3640080,3641153,3641501,3642835);

INSERT INTO acore_world.`creature_template_model` (`CreatureID`,`Idx`,`CreatureDisplayID`,`DisplayScale`,`Probability`,`VerifiedBuild`)
SELECT entry+@OFF, idx, mid, scale, 1, 0 FROM (
  SELECT entry, 0 idx, modelid1 mid, scale FROM nelt_world.creature_template WHERE entry IN (40080,41153,41501,42835) AND modelid1>0
  UNION ALL SELECT entry, 1, modelid2, scale FROM nelt_world.creature_template WHERE entry IN (40080,41153,41501,42835) AND modelid2>0
  UNION ALL SELECT entry, 2, modelid3, scale FROM nelt_world.creature_template WHERE entry IN (40080,41153,41501,42835) AND modelid3>0
  UNION ALL SELECT entry, 3, modelid4, scale FROM nelt_world.creature_template WHERE entry IN (40080,41153,41501,42835) AND modelid4>0
) m;

